async function stage(page,series,voices=18){await page.evaluate(({series,voices})=>{const $=jQuery,L=Lampa;L.Storage.set('nova_plus_view','grid');
 const image='data:image/svg+xml,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="1600" height="900"><rect width="1600" height="900" fill="white"/><path d="M0 0H1600L0 900Z" fill="#e6bb67"/></svg>');L.TMDB.image=()=>image;L.Api.img=()=>image;
 const root=$('<div class="explorer"><div class="explorer__files"><div class="explorer__files-head"></div><div class="explorer__files-body"><div class="scroll"><div class="scroll__content"><div class="scroll__body"></div></div></div></div></div></div>').css({position:'fixed',inset:'60px 0 0',background:'#000',zIndex:30,overflowY:'auto'}).appendTo(document.body),filter=new L.Filter({search:false,sort:true,filter:true});root.find('.explorer__files-head').append(filter.render());filter.set('sort',[{title:'Test - 4K',source:'test',selected:true}]);filter.set('filter',series?[{stype:'season',title:'Сезон',items:[{title:'Сезон 1',selected:true}]},{stype:'voice',title:'Перевод',items:Array.from({length:voices},(_,i)=>({title:['Дубляж NETFLIX','1WIN Studio','Кубик в Кубе | Kubik³','Яроцкий Михаил | Kyberpunk'][i%4]+' '+i,selected:i===0}))}]:[]);
 const movie={id:799,title:'Проверка баннера',original_title:'Polish test',release_date:'2026-01-01',runtime:145,production_countries:[{iso_3166_1:'US',name:'United States of America'}],vote_average:8.5,backdrop_path:'/bright.jpg',source:'tmdb',...(series?{name:'Проверка сериала',number_of_seasons:1,seasons:[{season_number:1,episode_count:2}]}:{})};window.qaRoot=root;
 if(series){L.Timeline.update({hash:L.Utils.hash('11Polish test'),percent:100,time:3600,duration:3600});L.Timeline.update({hash:L.Utils.hash('12Polish test'),percent:40,time:1440,duration:3600});}else L.Timeline.update({hash:L.Utils.hash('Polish test'),percent:55,time:3300,duration:6000});
 for(let i=1;i<=2;i++)$('<div class="online-prestige online-prestige--full selector"><div class="online-prestige__img"><img></div><div class="online-prestige__title">'+(series?'Серия '+i+': Название серии ':'Озвучка ')+i+'</div>'+(series?'<div class="online-prestige__episode-number">'+i+'</div>':'')+'<div class="online-prestige__quality">1080p</div><div class="time-line"><div style="width:0%"></div></div></div>').appendTo(root.find('.scroll__body'));
 L.Activity.active=()=>({component:'online_test',movie,activity:{render:()=>root,component:{}}});L.Listener.send('activity',{type:'start'});
},{series,voices});await page.waitForTimeout(700);}

module.exports={stage};
